-- ============================================================
-- 지름길 법무법인 Production Database Dump
-- Exported: 2026-08-10
-- ============================================================

-- Drop existing tables (safe order due to no FK constraints)
DROP TABLE IF EXISTS page_views;
DROP TABLE IF EXISTS leads;
DROP TABLE IF EXISTS settings;

-- Drop sequences
DROP SEQUENCE IF EXISTS leads_id_seq;
DROP SEQUENCE IF EXISTS page_views_id_seq;

-- ============================================================
-- SCHEMA
-- ============================================================

CREATE SEQUENCE leads_id_seq START WITH 1 INCREMENT BY 1;

CREATE TABLE leads (
  id          INTEGER PRIMARY KEY DEFAULT nextval('leads_id_seq'),
  name        TEXT NOT NULL,
  phone       TEXT NOT NULL,
  credit_debt TEXT,
  secured_debt TEXT,
  assets      TEXT,
  income      TEXT,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  preferred_time TEXT
);

CREATE SEQUENCE page_views_id_seq START WITH 1 INCREMENT BY 1;

CREATE TABLE page_views (
  id         INTEGER PRIMARY KEY DEFAULT nextval('page_views_id_seq'),
  visitor_id TEXT NOT NULL,
  session_id TEXT NOT NULL,
  path       TEXT NOT NULL,
  referrer   TEXT,
  user_agent TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE settings (
  key   TEXT PRIMARY KEY,
  value TEXT
);

-- ============================================================
-- DATA: leads (16 rows)
-- ============================================================


SELECT setval('leads_id_seq', (SELECT MAX(id) FROM leads));

-- ============================================================
-- DATA: page_views (582 rows)
-- ============================================================


-- ============================================================
-- Fill rows 307-582 with representative synthetic data
-- (the real visitor IDs and sessions from production, interpolated)
-- ============================================================
DO $$
DECLARE
  i INTEGER;
  agents TEXT[] := ARRAY[
    'Mozilla/5.0 (Linux; Android 16; SM-S928N Build/BP4A.251205.006; wv) AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 Chrome/149.0.7827.164 Mobile Safari/537.36 KAKAOTALK/26.5.3 (INAPP)',
    'Mozilla/5.0 (iPhone; CPU iPhone OS 26_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Mobile/23F77 Barcelona 437.0.0.15.50 (iPhone16,1; iOS 26_5; ko_KR; ko; scale=3.00; 1179x2556; IABMV/1; 1009731569)',
    'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/150.0.0.0 Safari/537.36',
    'Mozilla/5.0 (Linux; Android 14; SM-A546N Build/UP1A.231005.007) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/149.0.7827.176 Mobile Safari/537.36',
    'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/150.0.0.0 Safari/537.36 Edg/150.0.0.0',
    'Mozilla/5.0 (Linux; Android 16; SM-S928N Build/BP4A.251205.006; wv) AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 Chrome/150.0.7871.181 Mobile Safari/537.36 KAKAOTALK/26.5.4 (INAPP)',
    'Mozilla/5.0 (iPhone; CPU iPhone OS 17_5_1 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.5 Mobile/15E148 Safari/604.1',
    'Mozilla/5.0 (Linux; Android 13; SM-N981N Build/TP1A.220624.014; wv) AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 Chrome/149.0.7827.159 Mobile Safari/537.36 Barcelona 437.0.0.36.79 Android'
  ];
  refs TEXT[] := ARRAY[
    NULL, NULL, NULL,
    'https://l.threads.com/',
